content.css:
.eclor-waterfall-root {
  width: 100%;
  height: 100%;
  font-family: "Segoe UI", "Segoe UI Web (West European)", "Helvetica Neue", Helvetica, Arial, sans-serif;
  background: transparent;
  overflow: hidden;
  position: relative;
}
.eclor-waterfall-root > svg {
  display: block;
  width: 100%;
  height: 100%;
}
.eclor-waterfall-root .wf-empty-preview > svg {
  display: block;
  width: 100%;
  height: 100%;
  max-width: 420px;
  max-height: 240px;
}
.eclor-waterfall-root .wf-clickable {
  cursor: pointer;
  transition: filter 80ms ease-in-out;
}
.eclor-waterfall-root .wf-clickable:hover {
  filter: brightness(1.08);
}
.eclor-waterfall-root .wf-table-row {
  cursor: pointer;
  outline: none;
}
.eclor-waterfall-root .wf-table-row .wf-table-row-bg {
  fill: transparent;
  transition: fill 80ms ease-in-out;
}
.eclor-waterfall-root .wf-table-row:hover .wf-table-row-bg {
  fill: rgba(0, 0, 0, 0.04);
}
.eclor-waterfall-root .wf-table-row .wf-table-row-focus {
  visibility: hidden;
  pointer-events: none;
}
.eclor-waterfall-root .wf-table-row:focus-visible .wf-table-row-focus {
  visibility: visible;
}
.eclor-waterfall-root .wf-bar:focus,
.eclor-waterfall-root .wf-bar:focus-visible {
  outline: none;
}
.eclor-waterfall-root .wf-bar:focus-visible .wf-focus-ring {
  visibility: visible;
}
.eclor-waterfall-root .wf-focus-ring {
  visibility: hidden;
  pointer-events: none;
}
